function countMirrorPicks(digits: string): number {
  const n = digits.length;
  const pick: string[] = [];
  let count = 0;
  const go = (start: number): void => {
    if (pick.length === 5) {
      if (pick[0] === pick[4] && pick[1] === pick[3]) count++;
      return;
    }
    for (let i = start; i <= n - (5 - pick.length); i++) {
      pick.push(digits[i]);
      go(i + 1);
      pick.pop();
    }
  };
  go(0);
  return count % 1000000007;
}

