function countMirrorPicks(digits: string): number {
  const MOD = 1000000007;
  const s = Array.from(digits, ch => ch.charCodeAt(0) - 48);
  let total = 0;
  for (let a = 0; a <= 9; a++) {
    for (let b = 0; b <= 9; b++) {
      // dpK = ways to match the first K symbols of a, b, ?, b, a
      let d1 = 0, d2 = 0, d3 = 0, d4 = 0, d5 = 0;
      for (const c of s) {
        // go from the longest prefix down so each digit is used once per pick
        if (c === a) d5 = (d5 + d4) % MOD;
        if (c === b) d4 = (d4 + d3) % MOD;
        d3 = (d3 + d2) % MOD;
        if (c === b) d2 = (d2 + d1) % MOD;
        if (c === a) d1 = (d1 + 1) % MOD;
      }
      total = (total + d5) % MOD;
    }
  }
  return total;
}

