function countMirrorPicks(digits: string): number {
  const MOD = 1000000007;
  const n = digits.length;
  const s = Array.from(digits, ch => ch.charCodeAt(0) - 48);
  const right = new Int32Array(n * 100); // right[m*100 + x*10 + y]: pairs x then y after m
  let single = new Array(10).fill(0), pair = new Array(100).fill(0);
  for (let m = n - 1; m >= 0; m--) {
    for (let k = 0; k < 100; k++) right[m * 100 + k] = pair[k];
    const d = s[m];
    for (let a = 0; a < 10; a++) pair[d * 10 + a] += single[a];
    single[d]++;
  }
  single = new Array(10).fill(0);
  pair = new Array(100).fill(0);
  let total = 0;
  for (let m = 0; m < n; m++) {
    for (let a = 0; a < 10; a++) {
      for (let b = 0; b < 10; b++) {
        const l = pair[a * 10 + b];
        if (l) total = (total + l * right[m * 100 + b * 10 + a]) % MOD;
      }
    }
    const d = s[m];
    for (let a = 0; a < 10; a++) pair[a * 10 + d] += single[a];
    single[d]++;
  }
  return total;
}

